-- Host-only tutorial metadata. Programs are shared with executable fixtures and
-- generated player docs, never independently copied into a second help string.
local authoring='1. Clear your cursor and Ctrl+left-click the computer.\n2. In Reference, manually select and copy the entire code box for this computer.\n3. Switch to Editor, paste into an empty draft, then Validate, Save and Run.\n4. Read output in Console. Save alone does not replace the running program; use Apply after saving later changes.'
local computer='Research Native circuit computers (tc-circuit-computers). Craft one computer and supply continuous electricity using a powered pole in range.\n'
local wiring='\nDiscovery rule: use only the stated same-color NETWORK ports; ordinary poles and INPUT/OUTPUT/TARGETS sockets do not relay discovery.'
local stock='\n• Power the computer, logic handler and inserter. For a north-facing handler the ports are INPUT, NETWORK, OUTPUT from left to right.\n• Connect computer NETWORK red directly to logic NETWORK red.\n• Connect a separate stock chest (Read contents enabled, five normal-quality iron plates) to INPUT red.\n• Connect OUTPUT green to a powered inserter taking plates from a supply chest into an empty destination chest. Do not connect INPUT to OUTPUT.\n'
return {
  statistics={title='Native production statistics',purpose='Read local item, fluid and pollution totals/rates plus all 300 native iron-history samples without recording a second history.',
    setup=computer..'Research Recipe Searcher (tc-recipe-searcher). Craft one Production Statistics device from 8 iron plates, 5 electronic circuits and 2 advanced circuits. Supply 30 kW and connect computer NETWORK red directly to its NETWORK red. Produce some items, fluids or pollution to see nonempty maps. No item input, TARGETS wire or collector startup is needed. '..wiring,
    steps=authoring,
    expected='Console reports every recorded input total and one-minute rate, or explicitly says no recorded input. It then prints newest/oldest iron production and consumption per minute. Items retain quality names; pollution uses the whole surface, not only your force. Native UI rounds values; newest samples may still be incomplete.',
    failures='Missing wiring or power faults the query. A complete snapshot exceeding shared Data limits prints an explicit refusal, never empty data. Shared work/allocation E_BUDGET is fatal and cannot be caught. This small example is not an unlimited Console export. Mining the device never resets native history.',
    source='production-statistics-program',code=require('examples.production-statistics-program')},
  speaker={title='One speaker note',purpose='Submit one positional piano note and print whether the shared audio quota admitted it.',
    setup=computer..'Craft one vanilla programmable speaker (no additional mod research). Connect computer NETWORK red directly to the speaker native red socket. Power the speaker with a pole. Stay nearby on the same surface to listen. '..wiring,
    steps=authoring,expected='Console prints Note submitted: true on a quiet setup. A nearby listener can hear the first piano sample (F3). True confirms submission, not audible acknowledgement.',
    failures='Missing red wiring fails the assertion; no electrical service power faults playback. False means shared quota refusal, not a missing note name. Stop cannot cancel a sample already submitted. Run again to request another note; do not busy-loop retries.',
    source='reference-speaker',code=require('examples.reference-speaker')},
  logic={title='Stock-controlled inserter',purpose='Enable an inserter while a separate stock chest contains fewer than 100 normal iron plates.',
    setup=computer..'Craft one logic handler. '..stock..'In the inserter native circuit GUI enable circuit-controlled enable/disable with virtual signal A > 0. '..wiring,
    steps=authoring,expected='Console prints Controller subscribed. At five stock plates the handler emits A=1 and the supplied inserter moves items. At 100 stock plates it clears A and the inserter stops after any in-flight item settles. Change the stock chest, not the supply chest, to test both states.',
    failures='No motion: check power, inserter direction, destination space, A > 0 and the three separate port roles. Missing discovery faults setup. Stop, fault or loss of the discovery path clears only the run\'s still-owned bank; another writer can take ownership. Quality is part of signal identity.',
    source='logic-controller',code=require('examples.logic-controller')},
  recipe={title='Find iron plate recipes',purpose='Print the installed smelting recipes that directly produce iron plates, without crafting anything.',
    setup=computer..'Research Recipe Searcher (tc-recipe-searcher) separately and craft one searcher. Power it and connect computer NETWORK red directly to its NETWORK red. No inventory, item input or TARGETS wire is needed. '..wiring,
    steps=authoring,expected='Console prints Iron plate smelting recipes: followed by a positive count, then exact names including iron-plate in base and Space Age. Installed mods can add matches; enabled state is not crafting feasibility.',
    failures='Missing red wiring fails the assertion; unpowered service faults the query. More than 50 matching recipes raises E_LIMIT instead of returning a partial list. The explicit smelting category narrows the query; a heavily modded category may still exceed limits. No recipe is unlocked or executed.',
    source='reference-recipe',code=require('examples.reference-recipe')},
  factory={title='Small factory dashboard',purpose='Configure one inserter, sample stock, publish expiring shared data and draw a two-line monitor dashboard.',
    setup=computer..'Craft one each: logic handler, KV database, monitor and Configurator. '..stock..'• Also connect computer NETWORK red to the database, monitor and Configurator NETWORK red.\n• Connect Configurator TARGETS green directly to the same inserter native green socket; this joins its OUTPUT green network, not INPUT or discovery.\n• Keep exactly that one inserter on TARGETS green and exactly one device of each type on discovery. Supply electricity to all four peripherals. A single monitor tile is enough. '..wiring,
    steps=authoring..' Wait at least 60 simulation ticks for the first update. Increase stock to 100 to test stopping, then reduce it to five.',
    expected='At five plates the monitor shows Iron: 5 and FILLING, the inserter is enabled by A=1, and the database inspector shows stock:iron fields count=5/status=FILLING. At 100, the monitor shows STOPPED and A is absent. The KV hash refreshes every 60 ticks with a three-second TTL.',
    failures='Use a new monitor or clear old contents first; the program owns only its first two rows. Do not run other screen/output writers during this tutorial. Missing devices, unpowered services or an invalid target fault the program; earlier successful configuration is not rolled back. Stop clears owned logic output but leaves the last display and native settings; KV telemetry then expires after three simulation seconds.',
    source='reference-factory',code=require('examples.reference-factory')},
  shared={title='Two-computer shared data',purpose='Prove that two computers share one physical database while a different database stays independent.',
    setup='Research Native circuit computers (tc-circuit-computers). Craft and power two computers and two physical KV databases.\n• Connect computer 1 NETWORK red and computer 2 NETWORK red directly to the SAME shared database NETWORK red.\n• Connect computer 2 NETWORK green directly to the OTHER database NETWORK green.\n• Do not connect the databases together on green; computer 1 needs no green cable. Keep one database reachable per color from computer 2. '..wiring,
    steps='First use computer 1: '..authoring..' Use the Computer 1 code below. Then use computer 2 and repeat Validate, Save and Run with the Computer 2 code. Wait at least 60 simulation ticks and inspect computer 2 Console and both database inspectors.',
    expected='Computer 2 Console prints FILLING / private=private. Its state records shared_count=5 and private_status=absent. Both computers see observer set to computer 2\'s ID on the shared red database; only the green database contains observer=private. Separate colors alone do not create separate storage on one physical database.',
    failures='One database on both colors fails the identity assertion; two physical databases are required. Disconnected or unpowered service faults the observer. An empty shared hash reports expired, not a made-up count. Stop does not erase either database. This writes the tutorial keys stock:iron and observer; use fresh databases rather than overwriting useful factory data.',
    prelude=require('examples.reference-writer'),prelude_source='reference-writer',
    source='shared-telemetry',code=require('examples.shared-telemetry')}
}
